# Writes src/trace_types.jl from the plotly.js schema in the `plotly_artifacts` artifact (see Artifacts.toml).
# Run after updating the artifact:  julia deps/generate.jl
using Pkg
Pkg.activate(@__DIR__)
Pkg.instantiate()

using JSON

root = joinpath(@__DIR__, "..")
dir = Pkg.Artifacts.ensure_artifact_installed("plotly_artifacts", joinpath(root, "Artifacts.toml"))
version = strip(read(joinpath(dir, "version.txt"), String))
schema = JSON.parsefile(joinpath(dir, "plot-schema.json"))
types = sort!(collect(keys(schema["traces"])))

open(joinpath(root, "src", "trace_types.jl"), "w") do io
    println(io, "# Generated by deps/generate.jl from plotly.js $version's plot-schema.json.  Don't edit by hand.")
    println(io, "# The trace types (keys of `schema().traces`), so `plot.<type>` works without JSON.jl loaded.")
    println(io, "const TRACE_TYPES = (")
    foreach(t -> println(io, "    ", repr(Symbol(t)), ","), types)
    println(io, ")")
end
